 # CartStock
-Implement the public API specified in SPEC.md.
+
+```js
+import { createStockroom } from './src/stockroom.js';
+
+const stockroom = createStockroom({ stock: { mug: 4, plate: 2 } });
+const hold = stockroom.reserve({ id: 'cart-17', owner: 'customer-8', items: { mug: 2 }, ttl: 300 });
+console.log(hold, stockroom.availability());
+
+// Confirm using the version returned by reserve; advance logical time explicitly.
+stockroom.confirm({ id: hold.id, owner: hold.owner, version: hold.version });
+stockroom.advance(300);
+```
diff --git a/src/stockroom.js b/src/stockroom.js
index b0bb026..c60ce07 100644
--- a/src/stockroom.js
+++ b/src/stockroom.js
@@ -1,2 +1,217 @@
-export function createStockroom() { throw new Error('Not implemented'); }
-export function restoreStockroom() { throw new Error('Not implemented'); }
+const SKU_PATTERN = /^[A-Za-z][A-Za-z0-9_-]{0,31}$/;
+
+function fail(code, message) {
+  const error = new Error(message);
+  error.code = code;
+  throw error;
+}
+
+function isRecord(value) {
+  return value !== null && typeof value === 'object' && !Array.isArray(value);
+}
+
+function copyMap(value) {
+  return Object.fromEntries(Object.keys(value).map((key) => [key, value[key]]));
+}
+
+function validateMap(value, { nonempty, positive, known } = {}) {
+  if (!isRecord(value)) fail('INVALID', 'Expected an object map');
+  const keys = Object.keys(value);
+  if (nonempty && keys.length === 0) fail('INVALID', 'Expected a nonempty object map');
+  const result = {};
+  for (const sku of keys) {
+    if (!SKU_PATTERN.test(sku)) fail('INVALID', 'Invalid SKU');
+    const quantity = value[sku];
+    if (!Number.isSafeInteger(quantity) || (positive ? quantity <= 0 : quantity < 0)) {
+      fail('INVALID', 'Invalid quantity');
+    }
+    if (known && !known.has(sku)) fail('UNKNOWN_SKU', 'Unknown SKU');
+    result[sku] = quantity;
+  }
+  return result;
+}
+
+function validateIdentity(id, owner) {
+  if (typeof id !== 'string' || id.length < 1 || id.length > 64) fail('INVALID', 'Invalid reservation ID');
+  if (typeof owner !== 'string' || owner.length < 1 || owner.length > 64) fail('INVALID', 'Invalid owner');
+}
+
+function validateVersion(version) {
+  if (!Number.isSafeInteger(version) || version <= 0) fail('INVALID', 'Invalid version');
+}
+
+function sameItems(a, b) {
+  const keys = Object.keys(a);
+  return keys.length === Object.keys(b).length && keys.every((key) => Object.hasOwn(b, key) && a[key] === b[key]);
+}
+
+function view(reservation) {
+  return {
+    id: reservation.id,
+    owner: reservation.owner,
+    items: copyMap(reservation.items),
+    expiresAt: reservation.expiresAt,
+    state: reservation.state,
+    version: reservation.version,
+  };
+}
+
+function buildStockroom(onHandInput, now, restoredReservations = []) {
+  const onHand = new Map(Object.entries(onHandInput));
+  const reservations = new Map();
+  for (const reservation of restoredReservations) reservations.set(reservation.id, reservation);
+
+  function availability() {
+    const result = Object.fromEntries(onHand);
+    for (const reservation of reservations.values()) {
+      if (reservation.state !== 'held') continue;
+      for (const [sku, quantity] of Object.entries(reservation.items)) result[sku] -= quantity;
+    }
+    return result;
+  }
+
+  function validateItems(items) {
+    return validateMap(items, { nonempty: true, positive: true, known: new Set(onHand.keys()) });
+  }
+
+  function find(id) {
+    if (typeof id !== 'string' || id.length < 1 || id.length > 64) fail('INVALID', 'Invalid reservation ID');
+    const reservation = reservations.get(id);
+    if (!reservation) fail('UNKNOWN_RESERVATION', 'Unknown reservation');
+    return reservation;
+  }
+
+  function checkCommand(input) {
+    if (!isRecord(input)) fail('INVALID', 'Expected command object');
+    const { id, owner, version } = input;
+    validateIdentity(id, owner);
+    validateVersion(version);
+    const reservation = find(id);
+    if (reservation.owner !== owner) fail('FORBIDDEN', 'Owner does not match');
+    if (reservation.state !== 'held') fail('STATE', 'Reservation is not held');
+    if (reservation.version !== version) fail('VERSION_CONFLICT', 'Reservation version does not match');
+    return reservation;
+  }
+
+  const api = {
+    reserve(input) {
+      if (!isRecord(input)) fail('INVALID', 'Expected reservation object');
+      const { id, owner, ttl } = input;
+      validateIdentity(id, owner);
+      const items = validateItems(input.items);
+      if (!Number.isSafeInteger(ttl) || ttl <= 0) fail('INVALID', 'Invalid TTL');
+      const previous = reservations.get(id);
+      if (previous) {
+        if (previous.initialRequest.owner !== owner || previous.initialRequest.ttl !== ttl || !sameItems(previous.initialRequest.items, items)) {
+          fail('ID_CONFLICT', 'Reservation ID has a different initial request');
+        }
+        return view(previous);
+      }
+      const expiresAt = now + ttl;
+      if (!Number.isSafeInteger(expiresAt)) fail('INVALID', 'Deadline is not a safe integer');
+      const available = availability();
+      if (Object.entries(items).some(([sku, quantity]) => quantity > available[sku])) fail('INSUFFICIENT', 'Insufficient stock');
+      const reservation = {
+        id, owner, items, expiresAt, state: 'held', version: 1,
+        initialRequest: { owner, items: copyMap(items), ttl },
+      };
+      reservations.set(id, reservation);
+      return view(reservation);
+    },
+    amend(input) {
+      if (!isRecord(input)) fail('INVALID', 'Expected command object');
+      const nextItems = validateItems(input.items);
+      if (Object.hasOwn(input, 'ttl') && (!Number.isSafeInteger(input.ttl) || input.ttl <= 0)) fail('INVALID', 'Invalid TTL');
+      const reservation = checkCommand(input);
+      let nextExpiry = reservation.expiresAt;
+      if (Object.hasOwn(input, 'ttl')) {
+        nextExpiry = now + input.ttl;
+        if (!Number.isSafeInteger(nextExpiry)) fail('INVALID', 'Deadline is not a safe integer');
+      }
+      const available = availability();
+      for (const [sku, quantity] of Object.entries(reservation.items)) available[sku] += quantity;
+      if (Object.entries(nextItems).some(([sku, quantity]) => quantity > available[sku])) fail('INSUFFICIENT', 'Insufficient stock');
+      reservation.items = nextItems;
+      reservation.expiresAt = nextExpiry;
+      reservation.version += 1;
+      return view(reservation);
+    },
+    confirm(input) {
+      const reservation = checkCommand(input);
+      for (const [sku, quantity] of Object.entries(reservation.items)) onHand.set(sku, onHand.get(sku) - quantity);
+      reservation.state = 'confirmed';
+      reservation.version += 1;
+      return view(reservation);
+    },
+    cancel(input) {
+      const reservation = checkCommand(input);
+      reservation.state = 'cancelled';
+      reservation.version += 1;
+      return view(reservation);
+    },
+    get(id) { return view(find(id)); },
+    availability,
+    advance(time) {
+      if (!Number.isSafeInteger(time) || time < 0 || time < now) fail('INVALID_TIME', 'Invalid logical time');
+      now = time;
+      const expiredReservations = [...reservations.values()]
+        .filter((reservation) => reservation.state === 'held' && reservation.expiresAt <= time)
+        .sort((a, b) => a.expiresAt - b.expiresAt || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
+      for (const reservation of expiredReservations) {
+        reservation.state = 'expired';
+        reservation.version += 1;
+      }
+      return { now, expired: expiredReservations.map(({ id }) => id) };
+    },
+    snapshot() {
+      const entries = [...reservations.values()].sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
+      return {
+        schemaVersion: 1,
+        now,
+        onHand: Object.fromEntries(onHand),
+        reservations: entries.map((reservation) => ({
+          ...view(reservation),
+          initialRequest: {
+            owner: reservation.initialRequest.owner,
+            items: copyMap(reservation.initialRequest.items),
+            ttl: reservation.initialRequest.ttl,
+          },
+        })),
+      };
+    },
+  };
+  return api;
+}
+
+export function createStockroom(input = {}) {
+  if (!isRecord(input)) fail('INVALID', 'Expected stockroom options');
+  const { stock, now = 0 } = input;
+  if (!Number.isSafeInteger(now) || now < 0) fail('INVALID', 'Invalid logical time');
+  const validatedStock = validateMap(stock, { nonempty: true });
+  return buildStockroom(validatedStock, now);
+}
+
+export function restoreStockroom(snapshot) {
+  if (!isRecord(snapshot) || snapshot.schemaVersion !== 1 || !Number.isSafeInteger(snapshot.now) || snapshot.now < 0) {
+    fail('INVALID', 'Invalid snapshot');
+  }
+  const onHand = validateMap(snapshot.onHand, { nonempty: true });
+  if (!Array.isArray(snapshot.reservations)) fail('INVALID', 'Invalid reservations');
+  const restoredReservations = [];
+  for (const entry of snapshot.reservations) {
+    if (!isRecord(entry)) fail('INVALID', 'Invalid reservation entry');
+    const { id, owner, items, expiresAt, state, version, initialRequest } = entry;
+    validateIdentity(id, owner);
+    if (!Number.isSafeInteger(expiresAt) || expiresAt < 0 || !['held', 'confirmed', 'cancelled', 'expired'].includes(state) || !Number.isSafeInteger(version) || version <= 0) {
+      fail('INVALID', 'Invalid reservation state');
+    }
+    const currentItems = validateMap(items, { nonempty: true, positive: true, known: new Set(Object.keys(onHand)) });
+    if (!isRecord(initialRequest) || typeof initialRequest.owner !== 'string' || initialRequest.owner.length < 1 || initialRequest.owner.length > 64 || !Number.isSafeInteger(initialRequest.ttl) || initialRequest.ttl <= 0) {
+      fail('INVALID', 'Invalid initial request');
+    }
+    const initialItems = validateMap(initialRequest.items, { nonempty: true, positive: true, known: new Set(Object.keys(onHand)) });
+    restoredReservations.push({ id, owner, items: currentItems, expiresAt, state, version,
+      initialRequest: { owner: initialRequest.owner, items: initialItems, ttl: initialRequest.ttl } });
+  }
+  return buildStockroom(onHand, snapshot.now, restoredReservations);
+}
diff --git a/tests/acceptance.test.js b/tests/acceptance.test.js
new file mode 100644
index 0000000..15efedc
--- /dev/null
+++ b/tests/acceptance.test.js
@@ -0,0 +1,371 @@
+import { expect, test } from 'vitest';
+import { createStockroom, restoreStockroom } from '../src/stockroom.js';
+
+async function captureError(call) {
+  try {
+    await call();
+  } catch (error) {
+    return error;
+  }
+  return undefined;
+}
+
+// @aidept-case C-1
+test('[R-1][R-3][R-4][C-1] exports and reservation view', async () => {
+  // @aidept-step S-1
+  expect(typeof createStockroom).toBe('function');
+  // @aidept-step S-1
+  expect(typeof restoreStockroom).toBe('function');
+  const room = await createStockroom({ stock: { A: 1 } });
+  // @aidept-step S-1
+  expect(await room.availability()).toEqual({ A: 1 });
+  const made = await room.reserve({ id: 'r', owner: 'o', items: { A: 1 }, ttl: 1 });
+  const fetched = await room.get('r');
+  // @aidept-step S-2
+  expect(made).toEqual({ id: 'r', owner: 'o', items: { A: 1 }, expiresAt: 1, state: 'held', version: 1 });
+  // @aidept-step S-2
+  expect(Object.keys(made).sort()).toEqual(['expiresAt', 'id', 'items', 'owner', 'state', 'version']);
+  // @aidept-step S-2
+  expect(fetched).toEqual(made);
+});
+
+// @aidept-case C-2
+test('[R-2][C-2] validates inputs and distinguishes unknown SKU', async () => {
+  const invalidFactories = [
+    () => createStockroom({ stock: {} }),
+    () => createStockroom({ stock: { A: -1 } }),
+    () => createStockroom({ stock: { A: Number.MAX_SAFE_INTEGER + 1 } }),
+    () => createStockroom({ stock: { A: 1 }, now: -1 }),
+  ];
+  for (const factory of invalidFactories) {
+    const error = await captureError(factory);
+    // @aidept-step S-1
+    expect(error?.code).toBe('INVALID');
+  }
+  const room = await createStockroom({ stock: { A: 2 } });
+  const invalidReserves = [
+    () => room.reserve({ id: 'x', owner: 'o', items: {}, ttl: 1 }),
+    () => room.reserve({ id: 'x', owner: 'o', items: { A: 0 }, ttl: 1 }),
+    () => room.reserve({ id: '', owner: 'o', items: { A: 1 }, ttl: 1 }),
+    () => room.reserve({ id: 'x', owner: '', items: { A: 1 }, ttl: 1 }),
+    () => room.reserve({ id: 'x', owner: 'o', items: { A: 1 }, ttl: 0 }),
+    () => room.reserve({ id: 'x', owner: 'o', items: { A: 1 }, ttl: Number.MAX_SAFE_INTEGER + 1 }),
+  ];
+  for (const call of invalidReserves) {
+    const error = await captureError(call);
+    // @aidept-step S-1
+    expect(error?.code).toBe('INVALID');
+  }
+  const unknown = await captureError(() => room.reserve({ id: 'u', owner: 'o', items: { Z: 1 }, ttl: 1 }));
+  // @aidept-step S-2
+  expect(unknown?.code).toBe('UNKNOWN_SKU');
+  await room.reserve({ id: 'r', owner: 'o', items: { A: 1 }, ttl: 5 });
+  for (const command of [
+    () => room.amend({ id: 'r', owner: 'o', version: 0, items: { A: 1 } }),
+    () => room.confirm({ id: 'r', owner: 'o', version: 0 }),
+    () => room.cancel({ id: 'r', owner: 'o', version: 0 }),
+  ]) {
+    const error = await captureError(command);
+    // @aidept-step S-2
+    expect(error?.code).toBe('INVALID');
+  }
+  // @aidept-step S-2
+  expect(await room.get('r')).toMatchObject({ state: 'held', version: 1 });
+});
+
+// @aidept-case C-3
+test('[R-3][R-13][C-3] reserve is atomic on insufficient multi-SKU stock', async () => {
+  const room = await createStockroom({ stock: { A: 2, B: 1 } });
+  const beforeSnapshot = await room.snapshot();
+  const beforeAvailability = await room.availability();
+  const error = await captureError(() => room.reserve({ id: 'bad', owner: 'o', items: { A: 1, B: 2 }, ttl: 3 }));
+  // @aidept-step S-1
+  expect(error?.code).toBe('INSUFFICIENT');
+  // @aidept-step S-1
+  expect(await room.snapshot()).toEqual(beforeSnapshot);
+  // @aidept-step S-1
+  expect(await room.availability()).toEqual(beforeAvailability);
+  const made = await room.reserve({ id: 'r', owner: 'o', items: { A: 2, B: 1 }, ttl: 3 });
+  // @aidept-step S-2
+  expect(made).toEqual({ id: 'r', owner: 'o', items: { A: 2, B: 1 }, expiresAt: 3, state: 'held', version: 1 });
+  // @aidept-step S-2
+  expect(await room.availability()).toEqual({ A: 0, B: 0 });
+});
+
+// @aidept-case C-4
+test('[R-7][R-9][R-13][R-3][C-4] amend is atomic, credits prior hold, and replaces items', async () => {
+  const room = await createStockroom({ stock: { A: 2, B: 1 } });
+  const initial = await room.reserve({ id: 'r', owner: 'o', items: { A: 1, B: 1 }, ttl: 5 });
+  // @aidept-step S-1
+  expect(initial).toMatchObject({ state: 'held', version: 1, expiresAt: 5 });
+  // @aidept-step S-1
+  expect(await room.availability()).toEqual({ A: 1, B: 0 });
+  const before = await room.snapshot();
+  const error = await captureError(() => room.amend({ id: 'r', owner: 'o', version: 1, items: { A: 2, B: 2 } }));
+  // @aidept-step S-2
+  expect(error?.code).toBe('INSUFFICIENT');
+  // @aidept-step S-2
+  expect(await room.get('r')).toEqual(initial);
+  // @aidept-step S-2
+  expect(await room.availability()).toEqual({ A: 1, B: 0 });
+  // @aidept-step S-2
+  expect(await room.snapshot()).toEqual(before);
+  const amended = await room.amend({ id: 'r', owner: 'o', version: 1, items: { A: 2 } });
+  // @aidept-step S-3
+  expect(amended).toEqual({ id: 'r', owner: 'o', items: { A: 2 }, expiresAt: 5, state: 'held', version: 2 });
+  // @aidept-step S-3
+  expect(await room.availability()).toEqual({ A: 0, B: 1 });
+});
+
+// @aidept-case C-5
+test('[R-6][R-13][C-5] owner and state errors precede version checks', async () => {
+  const room = await createStockroom({ stock: { A: 3 } });
+  await room.reserve({ id: 'r', owner: 'o', items: { A: 1 }, ttl: 5 });
+  await room.reserve({ id: 'c', owner: 'o', items: { A: 1 }, ttl: 5 });
+  await room.cancel({ id: 'c', owner: 'o', version: 1 });
+  const before = await room.snapshot();
+  for (const call of [
+    () => room.amend({ id: 'r', owner: 'other', version: 99, items: { A: 1 } }),
+    () => room.confirm({ id: 'r', owner: 'other', version: 99 }),
+    () => room.cancel({ id: 'r', owner: 'other', version: 99 }),
+  ]) {
+    const error = await captureError(call);
+    // @aidept-step S-1
+    expect(error?.code).toBe('FORBIDDEN');
+    // @aidept-step S-1
+    expect(await room.snapshot()).toEqual(before);
+  }
+  for (const call of [
+    () => room.amend({ id: 'c', owner: 'o', version: 1, items: { A: 1 } }),
+    () => room.confirm({ id: 'c', owner: 'o', version: 1 }),
+    () => room.cancel({ id: 'c', owner: 'o', version: 1 }),
+  ]) {
+    const error = await captureError(call);
+    // @aidept-step S-2
+    expect(error?.code).toBe('STATE');
+    // @aidept-step S-2
+    expect(await room.snapshot()).toEqual(before);
+  }
+});
+
+// @aidept-case C-6
+test('[R-7][R-8][R-9][R-3][C-6] amend confirm and cancel account for inventory', async () => {
+  const room = await createStockroom({ stock: { A: 3 } });
+  const made = await room.reserve({ id: 'r', owner: 'o', items: { A: 2 }, ttl: 5 });
+  // @aidept-step S-1
+  expect(made).toMatchObject({ state: 'held', version: 1, expiresAt: 5 });
+  // @aidept-step S-1
+  expect(await room.availability()).toEqual({ A: 1 });
+  const amended = await room.amend({ id: 'r', owner: 'o', version: 1, items: { A: 2 } });
+  // @aidept-step S-2
+  expect(amended).toMatchObject({ state: 'held', version: 2, expiresAt: 5 });
+  // @aidept-step S-2
+  expect(await room.availability()).toEqual({ A: 1 });
+  const beforeConfirm = await room.availability();
+  const confirmed = await room.confirm({ id: 'r', owner: 'o', version: 2 });
+  // @aidept-step S-3
+  expect(confirmed).toEqual({ id: 'r', owner: 'o', items: { A: 2 }, expiresAt: 5, state: 'confirmed', version: 3 });
+  // @aidept-step S-3
+  expect(await room.availability()).toEqual(beforeConfirm);
+  // @aidept-step S-3
+  expect((await room.snapshot()).onHand).toEqual({ A: 1 });
+  const cancelled = await room.reserve({ id: 'c', owner: 'o', items: { A: 1 }, ttl: 5 });
+  // @aidept-step S-4
+  expect(cancelled).toMatchObject({ id: 'c', state: 'held', version: 1, expiresAt: 5 });
+  const cancelledView = await room.cancel({ id: 'c', owner: 'o', version: 1 });
+  // @aidept-step S-4
+  expect(cancelledView).toEqual({ id: 'c', owner: 'o', items: { A: 1 }, expiresAt: 5, state: 'cancelled', version: 2 });
+  // @aidept-step S-4
+  expect((await room.snapshot()).onHand).toEqual({ A: 1 });
+  // @aidept-step S-4
+  expect(await room.availability()).toEqual({ A: 1 });
+});
+
+// @aidept-case C-7
+test('[R-5][R-7][C-7] reserve replay uses initial request after amendment', async () => {
+  const room = await createStockroom({ stock: { A: 3, B: 2 } });
+  const made = await room.reserve({ id: 'r', owner: 'o', items: { A: 1, B: 1 }, ttl: 5 });
+  // @aidept-step S-1
+  expect(made).toMatchObject({ id: 'r', state: 'held', version: 1, expiresAt: 5 });
+  const amended = await room.amend({ id: 'r', owner: 'o', version: 1, items: { A: 2 } });
+  // @aidept-step S-2
+  expect(amended).toEqual({ id: 'r', owner: 'o', items: { A: 2 }, expiresAt: 5, state: 'held', version: 2 });
+  const before = await room.snapshot();
+  const replay = await room.reserve({ id: 'r', owner: 'o', items: { B: 1, A: 1 }, ttl: 5 });
+  // @aidept-step S-3
+  expect(replay).toEqual(amended);
+  // @aidept-step S-3
+  expect(await room.snapshot()).toEqual(before);
+  const error = await captureError(() => room.reserve({ id: 'r', owner: 'o', items: { A: 1 }, ttl: 5 }));
+  // @aidept-step S-4
+  expect(error?.code).toBe('ID_CONFLICT');
+  // @aidept-step S-4
+  expect(await room.snapshot()).toEqual(before);
+});
+
+// @aidept-case C-8
+test('[R-10][R-13][R-3][C-8] advance expires at boundaries and orders results', async () => {
+  const room = await createStockroom({ stock: { A: 3 } });
+  const a = await room.reserve({ id: 'a', owner: 'o', items: { A: 1 }, ttl: 5 });
+  const b = await room.reserve({ id: 'b', owner: 'o', items: { A: 1 }, ttl: 5 });
+  const c = await room.reserve({ id: 'c', owner: 'o', items: { A: 1 }, ttl: 3 });
+  // @aidept-step S-1
+  expect([a.expiresAt, b.expiresAt, c.expiresAt]).toEqual([5, 5, 3]);
+  // @aidept-step S-1
+  expect([a.version, b.version, c.version]).toEqual([1, 1, 1]);
+  const early = await room.advance(2);
+  // @aidept-step S-2
+  expect(early).toEqual({ now: 2, expired: [] });
+  // @aidept-step S-2
+  expect(await room.get('c')).toMatchObject({ state: 'held', version: 1 });
+  const boundary = await room.advance(5);
+  // @aidept-step S-3
+  expect(boundary).toEqual({ now: 5, expired: ['c', 'a', 'b'] });
+  // @aidept-step S-3
+  expect(await room.get('a')).toMatchObject({ state: 'expired', version: 2, expiresAt: 5 });
+  // @aidept-step S-3
+  expect(await room.get('c')).toMatchObject({ state: 'expired', version: 2, expiresAt: 3 });
+  const repeated = await room.advance(5);
+  // @aidept-step S-4
+  expect(repeated).toEqual({ now: 5, expired: [] });
+  const before = await room.snapshot();
+  for (const time of [4, -1, Number.MAX_SAFE_INTEGER + 1]) {
+    const error = await captureError(() => room.advance(time));
+    // @aidept-step S-5
+    expect(error?.code).toBe('INVALID_TIME');
+    // @aidept-step S-5
+    expect(await room.snapshot()).toEqual(before);
+  }
+});
+
+// @aidept-case C-9
